SELECT CASE  WHEN ? = ? THEN 0 WHEN EXISTS ( SELECT 1 FROM adj_knows k1 WHERE k1.src = ? AND k1.dst = ? ) THEN 1 WHEN EXISTS ( SELECT 1 FROM adj_knows k1 JOIN adj_knows k2 ON k2.src = k1.dst WHERE k1.src = ? AND k2.dst = ? ) THEN 2 WHEN EXISTS ( SELECT 1 FROM adj_knows k1 JOIN adj_knows k2 ON k2.src = k1.dst JOIN adj_knows k3 ON k3.src = k2.dst WHERE k1.src = ? AND k3.dst = ? ) THEN 3 WHEN EXISTS ( SELECT 1 FROM adj_knows k1 JOIN adj_knows k2 ON k2.src = k1.dst JOIN adj_knows k3 ON k3.src = k2.dst JOIN adj_knows k4 ON k4.src = k3.dst WHERE k1.src = ? AND k4.dst = ? ) THEN 4 WHEN EXISTS ( SELECT 1 FROM adj_knows k1 JOIN adj_knows k2 ON k2.src = k1.dst JOIN adj_knows k3 ON k3.src = k2.dst JOIN adj_knows k4 ON k4.src = k3.dst JOIN adj_knows k5 ON k5.src = k4.dst WHERE k1.src = ? AND k5.dst = ? ) THEN 5 WHEN EXISTS ( SELECT 1 FROM adj_knows k1 JOIN adj_knows k2 ON k2.src = k1.dst JOIN adj_knows k3 ON k3.src = k2.dst JOIN adj_knows k4 ON k4.src = k3.dst JOIN adj_knows k5 ON k5.src = k4.dst JOIN adj_knows k6 ON k6.src = k5.dst WHERE k1.src = ? AND k6.dst = ? ) THEN 6 ELSE -1 END AS length
